const copy={services:{caption:'For local investors, landlords and housing operators.',kicker:'A PLACE TO STAY. A REASON TO STAY.',title:'Purpose-built housing for a tenant who actually stays.',body:'Healthcare assignments often mean months away from home. Haven gives housing operators a focused offering: a private place to sleep, cook and settle in, close to the work that brought someone here.',benefits:[['Designed around longer stays','A dedicated home can support the routines of a multi-month assignment. Validate local demand, rental budgets and seasonal occupancy before investing.'],['A private place to stand out','Offer a complete home with a kitchenette, bathroom and dedicated workspace. Furnished-housing marketplaces can be part of your leasing strategy.'],['A cluster that can grow','Explore a phased site plan with utilities and access considered from the start. Add homes as your local market and approvals support expansion.']],approach:'Start with the local need. Build from there.',approachBody:'A Haven cluster can begin with a modest number of homes and a clear understanding of local demand. Site planning sets the foundation for what comes next.',step1:'Understand the market',step1Body:'Speak with local facilities and staffing contacts about assignment lengths, housing needs and realistic rental budgets.',step3:'Build a place people choose',step3Body:'Create a manageable cluster with private homes, simple outdoor space and an operating plan for furnished stays.',cta:'See what a Haven cluster could look like near your local hospital.',ctaBody:'The useful starting point is your location, your site and the number of homes you have in mind. Every project begins with those particulars.'},hospitals:{caption:'For hospital administrators, HR teams and staffing coordinators.',kicker:'LOOK AFTER THE PEOPLE WHO LOOK AFTER YOURS.',title:'The housing gap is costing you nurses.',body:'An assignment is more than a shift. Healthcare travelers also need somewhere to live. Haven offers a way to explore private, dignified housing near your facility as part of your recruitment and staffing strategy.',benefits:[['Make the move feel possible','A clear housing option can help travelers picture life in your community. Plan around the needs of the people you are trying to bring in.'],['Give rest a place of its own','A private bathroom, a kitchen and a quiet place to sleep support everyday life between shifts. A dedicated workspace makes room for calls and personal time.'],['Bring the right people together','Facilities, HR, finance and a local housing operator can shape a workable plan. Discuss ownership, maintenance and resident management early.']],approach:'Plan around your people. Then your site.',approachBody:'Begin with your staffing needs and the realities of your community. Haven is a housing concept to explore with your facility and local partners.',step1:'Define the staffing need',step1Body:'Identify the roles, assignment lengths and number of residents you need to accommodate, including the needs of staff working nights.',step3:'Agree how it will operate',step3Body:'Evaluate hospital ownership or a housing partner, operating costs and capital funding with your finance team. Financing eligibility is project-specific.',cta:'Talk about what a housing solution could look like for your facility.',ctaBody:'Start with your facility, the people you need to accommodate and any land or local partners already in the conversation.'}};
let audience='services';const text=(id,value)=>document.getElementById(id).textContent=value;
function selectAudience(view){audience=view;const c=copy[view];document.querySelectorAll('[data-view]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.view===view)));[['audience-caption',c.caption],['pitch-kicker',c.kicker],['pitch-title',c.title],['pitch-copy',c.body],['approach-title',c.approach],['approach-copy',c.approachBody],['step1-title',c.step1],['step1-copy',c.step1Body],['step3-title',c.step3],['step3-copy',c.step3Body],['cta-title',c.cta],['cta-copy',c.ctaBody]].forEach(([id,v])=>text(id,v));const container=document.getElementById('benefits');container.replaceChildren(...c.benefits.map(([title,body],i)=>{const article=document.createElement('article');article.className='benefit';const n=document.createElement('span');n.textContent='0'+(i+1);const h=document.createElement('h3');h.textContent=title;const p=document.createElement('p');p.textContent=body;article.append(n,h,p);return article}));}
document.querySelectorAll('[data-view]').forEach(button=>button.addEventListener('click',()=>selectAudience(button.dataset.view)));selectAudience('services');
document.getElementById('brief-form').addEventListener('submit',event=>{event.preventDefault();const f=new FormData(event.currentTarget);const content=['SUNDELLO HAVEN 320 — PROJECT DISCUSSION BRIEF','Perspective: '+(audience==='services'?'Housing operator / services':'Hospital'),'Location / facility: '+f.get('location'),'Homes: '+f.get('homes'),'Notes: '+(f.get('notes')||'Not provided'),'','Questions to explore:','• Site access, utilities and local approvals','• Resident needs and assignment lengths','• Foundation engineering and accessibility','• Project budget, timing and operating responsibilities','','Concept discussion inquiry.'].join('\n');window.location.href='mailto:blair@enterlectual.com?subject='+encodeURIComponent('Haven 320 inquiry — '+f.get('location'))+'&body='+encodeURIComponent(content);text('form-status','Your email app will open with the inquiry. If it does not, email blair@enterlectual.com directly.');});
